package com.wayrapass.controller;import com.wayrapass.dto.request.CatalogRequests;import com.wayrapass.dto.response.CatalogResponses;import com.wayrapass.service.CatalogService;import jakarta.validation.Valid;import lombok.RequiredArgsConstructor;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/route-stops") @RequiredArgsConstructor public class RouteStopController{private final CatalogService s;@GetMapping("/route/{routeId}") public List<CatalogResponses.RouteStop> all(@PathVariable Long routeId){return s.routeStops(routeId);}@PostMapping @ResponseStatus(HttpStatus.CREATED) @PreAuthorize("hasRole('COORDINATOR')") public CatalogResponses.RouteStop create(@Valid @RequestBody CatalogRequests.RouteStop r){return s.saveRouteStop(null,r);}@PutMapping("/{id}") @PreAuthorize("hasRole('COORDINATOR')") public CatalogResponses.RouteStop update(@PathVariable Long id,@Valid @RequestBody CatalogRequests.RouteStop r){return s.saveRouteStop(id,r);}@DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) @PreAuthorize("hasRole('COORDINATOR')") public void delete(@PathVariable Long id){s.deleteRouteStop(id);}}
